function subarrayGCD(nums, k) {
  const gcd = (a, b) => {
    while (b !== 0) {
      const rest = a % b;
      a = b;
      b = rest;
    }
    return a;
  };
  let count = 0;
  for (let start = 0; start < nums.length; start++) {
    let current = 0;
    for (let end = start; end < nums.length; end++) {
      current = gcd(current, nums[end]);
      if (current % k !== 0) {
        break;
      }
      if (current === k) {
        count++;
      }
    }
  }
  return count;
}

