function subarrayGCD(nums, k) {
  let total = 0;
  for (let i = 0; i < nums.length; i++) {
    for (let j = i; j < nums.length; j++) {
      const part = nums.slice(i, j + 1);
      let best = 0;
      for (let d = Math.min(...part); d >= 1; d--) {
        if (part.every(v => v % d === 0)) { best = d; break; }
      }
      if (best === k) total++;
    }
  }
  return total;
}

