function generate(rand, size) {
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'large') {
    const n = 1000;
    const k = pick(1, 50000);
    const top = Math.floor(1e9 / k);
    const nums = Array.from({ length: n }, () => rand() < 0.03 ? pick(1, 1e9) : k * pick(1, top));
    return [nums, k];
  }
  const n = pick(1, 8);
  const k = pick(1, 6);
  const nums = Array.from({ length: n }, () => rand() < 0.75 ? k * pick(1, 6) : pick(1, 30));
  return [nums, k];
}
